import type { StickerSource } from "@scout-ui/react";

/**
 * The docs site's printed-matter sticker set (original Scout UI artwork,
 * generated by tooling/docs-collage/generate.mjs into /public/collage).
 *
 * Site-only: it replaces the official pack wherever the docs use stickers as
 * decoration or as live specimen material. It is NOT part of
 * @scout-ui/stickers — places whose output must be importable code
 * (playground, component previews, examples, the sticker drawer contact sheet)
 * keep using the official v0.1 pack.
 */
export interface CollageSticker extends StickerSource {
  readonly id: string;
  readonly name: string;
  readonly src: string;
  readonly width: number;
  readonly height: number;
}

function collage(id: string, name: string): CollageSticker {
  return { height: 400, id, name, src: `/collage/${id}.webp`, width: 400 };
}

export const collageStickers = [
  collage("ticket-stub", "Ticket stub"),
  collage("mixtape", "Sticker mixtape"),
  collage("airmail-envelope", "Airmail envelope"),
  collage("postage-stamp", "Postage stamp"),
  collage("embroidered-patch", "Embroidered patch"),
  collage("instant-photo", "Instant photo"),
  collage("floppy-disk", "Floppy disk"),
  collage("receipt", "Receipt"),
  collage("name-tag", "Name tag"),
  collage("fragile-label", "Fragile label"),
  collage("foil-seal", "Foil seal"),
  collage("pixel-heart", "Pixel heart"),
] as const satisfies readonly CollageSticker[];

export type CollageStickerId = (typeof collageStickers)[number]["id"];

export function collageSticker(id: CollageStickerId): CollageSticker {
  const sticker = collageStickers.find((candidate) => candidate.id === id);
  if (!sticker) throw new Error(`Unknown collage sticker: ${id}`);
  return sticker;
}
